<script setup lang="ts">
import {ref,watch,onMounted,onBeforeUnmount,nextTick} from 'vue';
import type {ECharts} from 'echarts/core';
const props=defineProps<{title:string;labels:string[];series:{name:string;data:(number|null)[];type?:string;stack?:string}[];unit:string;zoom?:boolean;min?:number;max?:number;range?:[number,number]}>();
const emit=defineEmits<{range:[value:[number,number]]}>();
const el=ref<HTMLElement>();const expanded=ref(false);let chart:ECharts|undefined;let observer:ResizeObserver|undefined;let disposed=false;let initializing:Promise<void>|undefined;
async function draw(){await nextTick();if(!el.value||disposed)return;if(!chart){initializing??=(async()=>{const runtime=await import('./chartRuntime');if(disposed||!el.value)return;chart=runtime.init(el.value);chart.on('datazoom',(event:any)=>{const e=event.batch?.[0]||event;if(Number.isFinite(e.start)&&Number.isFinite(e.end))emit('range',[e.start,e.end])})})();await initializing}if(disposed||!chart)return;
 chart.setOption({animation:false,color:['#245fd6','#e8a332','#34a77c','#8b76d5','#62b4da'],tooltip:{trigger:'axis'},legend:{type:'scroll',bottom:0,textStyle:{fontSize:11}},grid:{left:62,right:22,top:30,bottom:props.zoom===false?34:74},xAxis:{type:'category',data:props.labels,axisLabel:{fontSize:10,hideOverlap:true},axisLine:{lineStyle:{color:'#c6d1df'}}},yAxis:{type:'value',name:props.unit,min:props.min,max:props.max,splitLine:{lineStyle:{color:'#e8edf5'}},axisLabel:{fontSize:10}},dataZoom:props.zoom===false?[]:[{type:'inside',start:props.range?.[0]??0,end:props.range?.[1]??100},{type:'slider',height:14,bottom:32,start:props.range?.[0]??0,end:props.range?.[1]??100}],series:props.series.map(s=>({...s,type:s.type||'line',showSymbol:false,connectNulls:false,lineStyle:{width:2}}))},{notMerge:true});chart.resize()}
watch(()=>[props.labels,props.series,props.range],draw,{deep:true});watch(expanded,()=>nextTick(()=>chart?.resize()));
onMounted(()=>{observer=new ResizeObserver(()=>chart?.resize());if(el.value)observer.observe(el.value);draw()});onBeforeUnmount(()=>{disposed=true;observer?.disconnect();chart?.dispose()});
function exportImage(){if(!chart)return;const a=document.createElement('a');a.href=chart.getDataURL({type:'png',pixelRatio:2,backgroundColor:'#fff'});a.download=props.title+'.png';a.click()}
</script>
<template><article class="analysis-panel" :class="{expanded}"><div class="panel-title"><h3>{{title}}</h3><div><button @click="exportImage" title="导出当前图形 PNG">导出图形</button><button @click="expanded=!expanded" :aria-expanded="expanded">{{expanded?'恢复总览':'放大'}}</button></div></div><div v-if="!labels.length" class="chart-empty">当前任务未输出对应数据</div><div v-show="labels.length" ref="el" class="analysis-plot" :aria-label="title" role="img"></div></article></template>
<style scoped>
.analysis-panel{min-width:0;margin:0!important;background:#fff;border:1px solid #e4e9f0;border-radius:8px;padding:14px!important}.panel-title{display:flex;justify-content:space-between;align-items:center;gap:8px}.panel-title h3{margin:0;font-size:15px;color:#172943}.panel-title button{font-size:11px;padding:4px 8px;margin-left:5px}.analysis-plot{height:244px;width:100%}.chart-empty{height:244px;display:grid;place-items:center;color:#7c8ba1}.analysis-panel.expanded{position:fixed;inset:70px 25px 44px;z-index:90;display:flex;flex-direction:column;box-shadow:0 0 0 100vmax #17294344}.expanded .analysis-plot{flex:1;height:auto;min-height:280px}
</style>
